typedef struct IOReq {
  int pid;
  uint64_t lba;
  int size;
  int read; // 1 = read, 0 = write
  int credit; // dynamic, per-process
  int age;    // waiting cycles
  int arrival;
} IOReq;

int pick_next(IOReq q[], int n) {
  int best = -1;
  int best_prio = -1;
  for (int i = 0; i < n; i++) {
    if (q[i].arrival) {
      int prio = q[i].credit + (q[i].age > AGE_THRESHOLD ? 1 : 0);
      if (prio > best_prio) {
        best_prio = prio;
        best = i;
      }
    }
  }
  return best;
}
```

